class SemanticComputationGraphTest { @Test void rejectsCycleWithStableKeys(){var s=new CurriculumScope("2022_REVISED","MIDDLE",1,1,"A",1L,"m","n","s");var m=new ProblemSemanticModelV1(1,s,new SemanticProblemIntent(null,"low",null,"S","A",1,false),List.of(new SemanticParameter("R",SemanticValueType.INTEGER,"1","",false,null)),List.of(new SemanticComputation("A",SemanticOperation.ADD,List.of("R","B"),null,"",null),new SemanticComputation("B",SemanticOperation.ADD,List.of("R","A"),null,"",null)),List.of(),new SemanticPresentationPlan("",List.of(),List.of(),"",null,List.of()),List.of(),List.of());assertThatThrownBy(()->new SemanticComputationGraph().topologicallySort(m)).isInstanceOf(SemanticEvaluationException.class).hasMessageContaining("A, B");} }
